import json,re
src=open('data/raw/ZL3b-n.txt').read().splitlines(); clocks={}
for l in src:
 m=re.match(r'<(f\w+\.\d+),[^>]+>\s*<!([0-9]{2}):([0-9]{2})>',l)
 if m: clocks[m[1]]=int(m[2])%12+int(m[3])/60
shifts=[[14,8],[14,7],[16,10],[15,10],[14,0],[13,8]]
for fol,ks in zip(['f70v2','f72v1','f72v2','f72v3','f73r','f73v'],shifts):
 d=json.load(open(f'experiments/PIC-{fol}/fleet-fable/picture.json'))
 for ring,k in zip(['outer','inner'],ks):
  objs=[o for o in d['objects'] if re.fullmatch(ring+r'_figure_\d+',o['id'])]; n=len(objs)
  pos=[]
  for o in objs:
   p=o['features']['position']; matches=re.findall(r"(?:about )([\d.]+)(?::(\d+))? o'clock",p); h,m=matches[-1];pos.append(float(h)%12+(int(m)/60 if m else 0))
  labs=[clocks[o['label']] for o in objs]
  def score(shift):
   ds=[abs((x-labs[(j-shift)%n]+6)%12-6) for j,x in enumerate(pos)];return sum(ds)/n
  scores=[score(s) for s in range(n)];best=min(scores); print(fol,ring,n,'claimed',k,'dist',round(scores[k],3),'best',[i for i,s in enumerate(scores) if abs(s-best)<1e-8],'margin',round(sorted(scores)[1]-best,3),'baseline',round(scores[0],3),'threshold',round(6/n,3))
